import type { MigrateDownArgs, MigrateUpArgs } from '@payloadcms/db-postgres'

/**
 * Adds every new enum label, OUTSIDE the migration's wrapping transaction.
 *
 * ── Why this is a separate migration, and why it does not use `db` ──────────
 * Payload runs each migration inside a transaction it opens itself:
 * `runMigrationFile` in @payloadcms/drizzle calls `initTransaction(req)`, hands
 * `up()` a transaction-scoped `db`, then commits. There is no
 * `disableTransaction` flag in Payload 3.85 — I checked the runner.
 *
 * Two Postgres rules make that fatal for this change:
 *   · `ALTER TYPE ... ADD VALUE` cannot run inside a transaction block at all on
 *     PostgreSQL before 12; and
 *   · even on 12+, a label added in a transaction cannot be USED until that
 *     transaction commits — which the companion migration does, with
 *     `SET DEFAULT 'hero'`.
 *
 * So these statements go through `payload.db.pool` instead of the `db` argument.
 * That is a different connection from the pool, outside the wrapping
 * transaction, in autocommit — which satisfies both rules on every version.
 *
 * They are issued ONE PER `query()` call deliberately. node-postgres sends a
 * multi-statement string through the simple query protocol, which wraps the lot
 * in a single implicit transaction — reintroducing exactly the problem this file
 * exists to avoid.
 *
 * `IF NOT EXISTS` on every statement makes this re-runnable, so a database that
 * already has some labels (a dev box that was schema-pushed, or a partially
 * applied attempt) converges instead of erroring.
 *
 * The companion `..._editor_controls` migration runs next, in its own
 * transaction, which begins after this one has committed — so the labels are
 * visible to it. Do not merge the two files back together.
 */
