export async function up({ payload }: MigrateUpArgs): Promise<void> {
  const { pool } = payload.db as unknown as { pool: { query: (sql: string) => Promise<unknown> } }
  for (const statement of ENUM_ADDITIONS) {
    await pool.query(statement)
  }
  payload.logger.info(`Added ${ENUM_ADDITIONS.length} enum labels outside the migration transaction`)
}

export async function down(_args: MigrateDownArgs): Promise<void> {
  // Intentionally empty. Postgres cannot remove a label from an enum, and it does
  // not need to here: migrations revert in reverse order, so the companion
  // migration's `down()` runs first and rebuilds every one of these types from
  // scratch with the old label set (cast to text, DROP TYPE, CREATE TYPE, cast
  // back). By the time this runs there is nothing left to undo.
}
